import Foundation

/// One line of the Assistant tab's transcript: what the person sent, the
/// assistant's streamed reply, its progress notes between tool calls, a meta
/// line (a tool call, a failed result, an answer, compaction, a note the app
/// writes), or an error.
struct AssistantEntry: Equatable {
    enum Kind: String {
        case person, reply, progress, meta, error
    }

    let kind: Kind
    var text: String
}

/// What changed in the transcript, so a view redraws one entry rather than
/// all of them. `extended` carries the entry's WHOLE text now.
enum AssistantTranscriptChange: Equatable {
    case appended(AssistantEntry)
    case extended(index: Int, text: String)
    case cleared
    case usage(AssistantContextUsage)
    /// The conversation's cost so far (road map 13 P4, spec §11 P-7).
    case conversationCost(AssistantTurnCost)
}

/// The window's conversation as the person reads it (road map 12 A2): the
/// session's events turned into entries, and the context usage the helper
/// last reported. Rasterize's `AssistantPanelViewController.handleEvent`,
/// ported as storage with no views, so the tab and a later floating window
/// (spec §11 AI-4) draw the same transcript. It lives on
/// `EditorViewController.assistantTranscript`, beside the session; the view
/// holds none of it. Main only.
final class AssistantTranscript {
    private(set) var entries: [AssistantEntry] = []
    private(set) var usage = AssistantContextUsage()
    /// Every `cost` event since the last Clear or ended conversation, summed:
    /// the tab's Spend row (spec §11 P-7). In memory, so it carries across a
    /// helper restart and needs no spend folder.
    private(set) var conversationCost = AssistantTurnCost()

    /// Each change, as it happens.
    var onChange: ((AssistantTranscriptChange) -> Void)?

    /// The delta type ("text_delta" / "progress_delta") extending the newest
    /// entry; any other event, or a line the app writes, ends it.
    private var streamingType: String?
    /// The last question's sentence, which the answer event does not carry.
    private var questionSentence = ""
    /// The running turn's `cost` events, summed (road map 13 P2).
    private var turnCost = AssistantTurnCost()

    /// What the person sent.
    func person(_ text: String) {
        streamingType = nil
        append(.person, text)
    }

    /// A meta line the app writes (a settings change, say).
    func note(_ text: String) {
        streamingType = nil
        append(.meta, text)
    }

    /// One `AssistantSession` event.
    func take(_ event: [String: Any]) {
        let type = event["type"] as? String
        if type != streamingType { streamingType = nil }
        switch type {
        case "text_delta":
            delta(event["text"] as? String ?? "", type: "text_delta", kind: .reply)
        case "progress_delta":
            delta(event["text"] as? String ?? "", type: "progress_delta", kind: .progress)
        case "compaction_started":
            let used = (event["used"] as? Int ?? 0).formatted()
            append(.meta, "Compacting the conversation (\(used) tokens)…")
        case "compacted":
            let before = (event["before"] as? Int ?? 0).formatted()
            let after = (event["after"] as? Int ?? 0).formatted()
            append(
                .meta,
                "Compacted: \(before) → about \(after) tokens. Earlier renders are gone; "
                    + "the assistant re-renders when it needs to look.")
        case "compaction_failed":
            let reason = event["reason"] as? String ?? "no summary came back"
            append(
                .meta,
                "Compaction didn't finish (\(reason)); it will try again after the next turn.")
        case "tool_results_cleared":
            let uses = event["tool_uses"] as? Int ?? 0
            let tokens = (event["tokens"] as? Int ?? 0).formatted()
            append(
                .meta, "Cleared \(uses) old tool results (\(tokens) tokens) from the model's view.")
        case "context_usage":
            setUsage(
                AssistantContextUsage(
                    used: event["used"] as? Int ?? 0, limit: event["limit"] as? Int,
                    reported: true))
        case "tool_call":
            let name = event["name"] as? String ?? "?"
            append(.meta, name + Self.argumentSummary(event["arguments"]))
        case "tool_result":
            if event["is_error"] as? Bool == true {
                append(.meta, "failed: \(event["summary"] as? String ?? "")")
            }
        case "question":
            questionSentence = event["sentence"] as? String ?? ""
        case "answer":
            let by = event["by"] as? String ?? "person"
            if event["allowed"] as? Bool == true {
                append(.meta, "Allowed: \(questionSentence)")
            } else if by == "person" {
                append(.meta, "Declined: \(questionSentence)")
            } else {
                append(.meta, "Declined (\(by)): \(questionSentence)")
            }
        case "error":
            append(.error, event["message"] as? String ?? "Unknown error.")
        case "turn_started":
            turnCost = AssistantTurnCost()
        case "cost":
            turnCost.add(event)
            conversationCost.add(event)
            onChange?(.conversationCost(conversationCost))
        case "turn_finished":
            if let line = turnCost.line { append(.meta, line) }
            turnCost = AssistantTurnCost()
        default:
            break
        }
    }

    /// Clear: every entry gone, the cost and the usage back to none. The
    /// window size is the model's, so it is kept.
    func clear() {
        entries = []
        streamingType = nil
        questionSentence = ""
        turnCost = AssistantTurnCost()
        onChange?(.cleared)
        resetConversationCost()
        setUsage(AssistantContextUsage(used: 0, limit: usage.limit, reported: usage.reported))
    }

    /// The conversation ended under the transcript (a key or model change):
    /// the note says so, and the cost and the usage start over.
    func endConversation(note text: String) {
        note(text)
        turnCost = AssistantTurnCost()
        resetConversationCost()
        setUsage(AssistantContextUsage(used: 0, limit: usage.limit, reported: usage.reported))
    }

    /// " (k: v, …)" for a tool call's arguments, sorted, `project` dropped,
    /// the first 70 characters; "" when there is nothing to show.
    static func argumentSummary(_ arguments: Any?) -> String {
        guard let arguments = arguments as? [String: Any], !arguments.isEmpty else { return "" }
        let parts = arguments
            .filter { $0.key != "project" }
            .map { "\($0.key): \(compact($0.value))" }
            .sorted()
            .joined(separator: ", ")
        guard !parts.isEmpty else { return "" }
        return " (\(String(parts.prefix(70))))"
    }

    /// A string as itself; anything else as one line of JSON, so an id array
    /// reads `[3,4]` and a boolean `true`.
    private static func compact(_ value: Any) -> String {
        if let string = value as? String { return string }
        guard
            JSONSerialization.isValidJSONObject([value]),
            let data = try? JSONSerialization.data(
                withJSONObject: value, options: [.fragmentsAllowed, .sortedKeys]),
            let text = String(data: data, encoding: .utf8)
        else { return "\(value)" }
        return text
    }

    // MARK: - Private

    private func append(_ kind: AssistantEntry.Kind, _ text: String) {
        let entry = AssistantEntry(kind: kind, text: text)
        entries.append(entry)
        onChange?(.appended(entry))
    }

    /// Streams into the newest entry while the same delta type runs; the
    /// first delta of a run opens an entry.
    private func delta(_ text: String, type: String, kind: AssistantEntry.Kind) {
        guard streamingType == type, let last = entries.indices.last else {
            append(kind, text)
            streamingType = type
            return
        }
        entries[last].text += text
        onChange?(.extended(index: last, text: entries[last].text))
    }

    private func resetConversationCost() {
        conversationCost = AssistantTurnCost()
        onChange?(.conversationCost(conversationCost))
    }

    private func setUsage(_ next: AssistantContextUsage) {
        usage = next
        onChange?(.usage(next))
    }
}
import Foundation

/// The window's live context, as it is when the person sends a message: the
/// block `AssistantPrompt.message` puts in front of the person's text (spec
/// §11 AI-15). The system prompt is fixed for a session, so what changes
/// between turns — the playhead, the selection, the open nest — rides on the
/// message instead. Each label is a key of `get_project`'s answer, and the
/// system prompt names the block by `tag`. Road map 12 A3.
struct AssistantLiveContext: Equatable {
    let name: String
    let path: String?
    let scope: UInt32?
    let playhead: Ticks
    /// Ascending.
    let selection: [UInt32]

    /// The block's element name; the system prompt interpolates it.
    static let tag = "framejob_context"

    init(name: String, path: String?, scope: UInt32?, playhead: Ticks, selection: [UInt32]) {
        self.name = name
        self.path = path
        self.scope = scope
        self.playhead = playhead
        self.selection = selection
    }

    /// The document's context, read as `get_project` reads it. Main only.
    init(document: ProjectDocument) {
        assert(Thread.isMainThread)
        self.init(
            name: document.displayName ?? "Untitled", path: AgentServer.path(of: document),
            scope: document.scope, playhead: document.playhead,
            selection: document.selection.sorted())
    }

    /// The block, with no trailing newline.
    var text: String {
        let seconds = String(format: "%.3f", Double(playhead) / Double(ReelTime.perSecond))
        let lines = [
            "<\(Self.tag)>",
            "name: \(name)",
            "path: " + (path ?? "none (never saved)"),
            "scope: "
                + (scope.map { "\($0) (a nest is open: ids and times are its own)" }
                    ?? "none (the timeline is open)"),
            "playhead: \(playhead) (\(seconds) s)",
            "selection: "
                + (selection.isEmpty ? "none" : selection.map(String.init).joined(separator: ", ")),
            "</\(Self.tag)>",
        ]
        return lines.joined(separator: "\n")
    }
}
import AppKit

/// How full the assistant conversation's context is: tokens in play after
/// the last response, against the model's context window, both reported by
/// the helper (`context_usage`). Rasterize's, ported.
struct AssistantContextUsage: Equatable {
    var used = 0
    /// The model's context window; nil until the helper has looked it up, or
    /// when the Models API did not say.
    var limit: Int?
    /// False until the helper has reported at all.
    var reported = false
}

/// The Assistant tab's context meter, inline along the tab's top rather than in
/// Rasterize's popover: a square 3 pt track filled to the used fraction (the
/// block slider's track, `Controls.swift`), and the figures beside a "Context"
/// micro label. Road map 12 A2.
final class AssistantContextMeterView: NSView {
    private let bar = AssistantContextBar()
    private let title = NSTextField(labelWithString: "")
    let figuresLabel = NSTextField(labelWithString: "")
    private var usage = AssistantContextUsage()
    /// Measures a rung in the label's font; never in the hierarchy.
    private let measure = NSTextField(labelWithString: "")

    init() {
        super.init(frame: .zero)
        title.attributedStringValue = DS.microLabel("Context")
        title.setContentHuggingPriority(.required, for: .horizontal)
        title.setContentCompressionResistancePriority(.required, for: .horizontal)
        figuresLabel.font = DS.mono(10)
        measure.font = DS.mono(10)
        figuresLabel.textColor = DS.textFaint
        figuresLabel.lineBreakMode = .byTruncatingTail
        figuresLabel.alignment = .right
        figuresLabel.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        figuresLabel.setAccessibilityIdentifier("assistant.context")
        for view in [title, figuresLabel, bar] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
        }
        // A label's frame is 2 pt wider than its text on each side; the
        // insets keep both frames inside this view.
        NSLayoutConstraint.activate([
            title.topAnchor.constraint(equalTo: topAnchor),
            title.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 2),
            figuresLabel.firstBaselineAnchor.constraint(equalTo: title.firstBaselineAnchor),
            figuresLabel.leadingAnchor.constraint(
                greaterThanOrEqualTo: title.trailingAnchor, constant: 8),
            figuresLabel.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -2),
            bar.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 4),
            bar.leadingAnchor.constraint(equalTo: leadingAnchor),
            bar.trailingAnchor.constraint(equalTo: trailingAnchor),
            bar.heightAnchor.constraint(equalToConstant: 3),
            bar.bottomAnchor.constraint(equalTo: bottomAnchor),
        ])
        update(AssistantContextUsage())
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AssistantContextMeterView does not support NSCoder")
    }

    func update(_ usage: AssistantContextUsage) {
        self.usage = usage
        figuresLabel.toolTip = Self.figures(usage)
        showFittingFigure()
        bar.fraction = Self.fraction(usage)
    }

    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        showFittingFigure()
    }

    /// The first rung of `figureLadder` that fits beside the title, or the
    /// last when none does. The 12 is the constraints' 2 pt inset, 8 pt gap
    /// and 2 pt inset.
    private func showFittingFigure() {
        let room = bounds.width - title.intrinsicContentSize.width - 12
        let shown = fittingRung(Self.figureLadder(usage), room: room, measure: measure)
        if figuresLabel.stringValue != shown { figuresLabel.stringValue = shown }
    }

    /// The full figures — "Nothing reported yet", "N of L tokens · P%", or
    /// "N tokens (window size unknown)": `figureLadder`'s first rung.
    static func figures(_ usage: AssistantContextUsage) -> String {
        figureLadder(usage)[0]
    }

    /// The figures from longest to shortest: the full figures (`figures(_:)`)
    /// first, then "N / L · P%" and "P%", or "N tokens".
    static func figureLadder(_ usage: AssistantContextUsage) -> [String] {
        let used = usage.used.formatted()
        switch (usage.reported, usage.limit) {
        case (false, _):
            return ["Nothing reported yet"]
        case (true, let limit?) where limit > 0:
            let percent = (fraction(usage) * 100)
                .formatted(.number.precision(.fractionLength(0...1)))
            return [
                "\(used) of \(limit.formatted()) tokens · \(percent)%",
                "\(used) / \(limit.formatted()) · \(percent)%", "\(percent)%",
            ]
        case (true, _):
            return ["\(used) tokens (window size unknown)", "\(used) tokens"]
        }
    }

    private static func fraction(_ usage: AssistantContextUsage) -> Double {
        guard usage.reported, let limit = usage.limit, limit > 0 else { return 0 }
        return min(1, Double(usage.used) / Double(limit))
    }
}

/// The Assistant tab's Spend row (road map 13 P4, spec §11 P-7): a "Spend"
/// micro label and what the conversation has cost so far, as Frame Job
/// estimates it (`AssistantTurnCost.figure`, or its shorter rung where that
/// does not fit, P-8), laid out like the meter's label row.
final class AssistantConversationCostView: NSView {
    private let title = NSTextField(labelWithString: "")
    let figureLabel = NSTextField(labelWithString: "")
    private var cost = AssistantTurnCost()
    /// Measures a rung in the label's font; never in the hierarchy.
    private let measure = NSTextField(labelWithString: "")

    init() {
        super.init(frame: .zero)
        title.attributedStringValue = DS.microLabel("Spend")
        title.setContentHuggingPriority(.required, for: .horizontal)
        title.setContentCompressionResistancePriority(.required, for: .horizontal)
        figureLabel.font = DS.mono(10)
        measure.font = DS.mono(10)
        figureLabel.textColor = DS.textFaint
        figureLabel.lineBreakMode = .byTruncatingTail
        figureLabel.alignment = .right
        figureLabel.toolTip = AssistantTurnCost.figureTooltip
        figureLabel.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        figureLabel.setAccessibilityIdentifier("assistant.spend")
        for view in [title, figureLabel] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
        }
        // The meter's 2 pt insets: a label's frame is 2 pt wider than its text.
        NSLayoutConstraint.activate([
            title.topAnchor.constraint(equalTo: topAnchor),
            title.bottomAnchor.constraint(equalTo: bottomAnchor),
            title.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 2),
            figureLabel.firstBaselineAnchor.constraint(equalTo: title.firstBaselineAnchor),
            figureLabel.leadingAnchor.constraint(
                greaterThanOrEqualTo: title.trailingAnchor, constant: 8),
            figureLabel.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -2),
        ])
        update(AssistantTurnCost())
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AssistantConversationCostView does not support NSCoder")
    }

    func update(_ cost: AssistantTurnCost) {
        self.cost = cost
        showFittingFigure()
    }

    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        showFittingFigure()
    }

    /// The first rung of `figureLadder` that fits beside the title, or the
    /// last when none does (spec §11 P-8) — the meter's shape and its 12 pt.
    private func showFittingFigure() {
        let room = bounds.width - title.intrinsicContentSize.width - 12
        let shown = fittingRung(cost.figureLadder, room: room, measure: measure)
        if figureLabel.stringValue != shown { figureLabel.stringValue = shown }
    }
}

/// The first rung of `ladder` whose width in `measure`'s font fits `room`, or
/// the last when none does — the meter's and the Spend row's one search.
private func fittingRung(_ ladder: [String], room: CGFloat, measure: NSTextField) -> String {
    ladder.first { rung in
        measure.stringValue = rung
        return measure.intrinsicContentSize.width <= room
    } ?? ladder[ladder.count - 1]
}

/// A square track with the used fraction filled in the accent; the fill
/// turns to the meter's clip colour past 80%.
private final class AssistantContextBar: NSView {
    var fraction: Double = 0 {
        didSet { needsDisplay = true }
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.border.setFill()
        bounds.fill()
        guard fraction > 0 else { return }
        (fraction > 0.8 ? DS.meterClip : DS.accent).setFill()
        // At least a sliver, so a small conversation still shows as used.
        let width = max(2, bounds.width * CGFloat(fraction))
        NSRect(x: 0, y: 0, width: width, height: bounds.height).fill()
    }
}
