// The assistant helper: the agent loop, run by the Anthropic SDK's Tool
// Runner, in a separate process the app launches from Contents/Helpers. It
// speaks JSON lines over stdio (protocol.ts) and owns no tools itself: every
// tool call goes back to the app, which runs it through the same dispatcher
// its MCP server uses. Two apps carry agent/src/ byte for byte, Rasterize
// and Frame Job: a change is one diff applied to both, and whatever differs
// between them arrives in `configure`.

import Anthropic from "@anthropic-ai/sdk";
import type {
  BetaMessage,
  BetaTool,
  BetaMessageParam,
  BetaToolResultContentBlockParam,
} from "@anthropic-ai/sdk/resources/beta/messages";
import type { BetaRunnableTool } from "@anthropic-ai/sdk/lib/tools/BetaRunnableTool";
import { ToolError } from "@anthropic-ai/sdk/lib/tools/ToolError";
import { createInterface } from "node:readline";
import { price } from "./pricing";
import { initialPrices, refreshPrices } from "./priceTable";
import type { LoadedPrices, PriceOptions } from "./priceTable";
import type {
  CallToolResult,
  CatalogTool,
  ChatSettings,
  Configure,
  HostMessage,
  HelperEvent,
} from "./protocol";

/** Hard ceiling on API rounds within one turn. */
const MAX_ITERATIONS = 30;
/** Thinking counts toward this as well as the reply. */
const MAX_TOKENS = 32000;

const TOOL_SEARCH = {
  type: "tool_search_tool_bm25_20251119",
  name: "tool_search_tool_bm25",
} as const;

/**
 * Old tool results are cleared, when the user turns it on, only past this
 * many tokens in context and in chunks of at least CLEAR_AT_LEAST, so the
 * prompt cache breaks rarely. The API applies it per request, so it can
 * fire mid-turn; it never touches tool search results (server-side).
 */
const CLEAR_TRIGGER_TOKENS = 150_000;
const CLEAR_AT_LEAST_TOKENS = 50_000;
const CLEAR_KEEP_TOOL_USES = 5;

/** Betas every request carries: progress notes, refusal fallback, and compaction blocks. */
const BASE_BETAS = [
  "thinking-display-updates-2026-08-18",
  "server-side-fallback-2026-07-01",
  "compact-2026-09-04",
];

let client: Anthropic | undefined;
let config: Configure | undefined;
/** Chat Settings; configure sets them and a settings message replaces them between turns. */
let settings: ChatSettings = { auto_compact_tokens: 300_000, clear_tool_results: false };
let tools: BetaRunnableTool[] = [];
let history: BetaMessageParam[] = [];
let turn: AbortController | undefined;
let nextCallID = 0;
/** Tokens in the conversation as of the last response, and the model's window. */
let contextUsed = 0;
let contextLimit: number | null = null;
const pendingCalls = new Map<string, (result: CallToolResult | null) => void>();
/** The price table in force; a turn takes it once, at its start (spec §11 P-5). */
let prices: LoadedPrices | undefined;

function emit(event: HelperEvent) {
  process.stdout.write(JSON.stringify(event) + "\n");
}

function configure(message: Configure) {
  config = message;
  client = new Anthropic({
    apiKey: message.api_key,
    baseURL: message.api_base ?? "https://api.anthropic.com",
    maxRetries: 3,
  });
  const core = new Set(message.core_tools);
  tools = message.tools.map((entry) => runnableTool(entry, core));
  settings = message.settings;
  void lookUpContextLimit(message.model);
  setUpPrices({ cache: message.price_cache, feed: message.price_feed });
}

/** The prices at `configure`: reported now when no refresh is due, else once
 *  the refresh settles, in the same continuation that puts it in force. */
function setUpPrices(options: PriceOptions) {
  const initial = initialPrices(options);
  prices = initial.prices;
  if (!initial.refreshDue) {
    emit({ type: "prices", source: initial.prices.source });
    return;
  }
  void refreshPrices(initial.prices, options).then((loaded) => {
    prices = loaded;
    emit({ type: "prices", source: loaded.source });
  });
}

/** What one response cost, at the prices its turn started with; `partial` for one cut short. */
function emitCost(message: BetaMessage, turnPrices: LoadedPrices, partial?: true) {
  emit({
    type: "cost",
    model: message.model,
    usage: message.usage,
    cost: price(message.usage, message.model, turnPrices.table),
    prices: turnPrices.source,
    ...(partial ? { partial } : {}),
  });
}

/** The model's context window, from the Models API, for the panel's meter. */
async function lookUpContextLimit(model: string) {
  try {
    const info = await client!.models.retrieve(model);
    contextLimit = info.max_input_tokens ?? null;
  } catch {
    contextLimit = null; // the meter shows usage without a limit
  }
  emitContextUsage();
}

function emitContextUsage() {
  emit({ type: "context_usage", used: contextUsed, limit: contextLimit });
}

/** Wraps one catalog entry: running it asks the app and waits for the answer. */
function runnableTool(entry: CatalogTool, core: ReadonlySet<string>): BetaRunnableTool {
  return {
    name: entry.name,
    description: entry.description,
    input_schema: entry.inputSchema as BetaTool["input_schema"],
    defer_loading: core.has(entry.name) ? undefined : true,
    parse: (input: unknown) => input,
    run: async (input: unknown) => {
      emit({ type: "tool_call", name: entry.name, arguments: input });
      const callID = String(++nextCallID);
      const result = await new Promise<CallToolResult | null>((resolve) => {
        pendingCalls.set(callID, resolve);
        emit({ type: "tool_request", call_id: callID, name: entry.name, arguments_json: JSON.stringify(input) });
      });
      const { blocks, isError, summary } = convertToolResult(result);
      emit({ type: "tool_result", name: entry.name, is_error: isError, summary });
      if (isError) throw new ToolError(blocks);
      return blocks;
    },
  };
}

/** MCP CallToolResult -> Messages API tool_result content, plus a one-line summary for the panel. */
function convertToolResult(result: CallToolResult | null): {
  blocks: BetaToolResultContentBlockParam[];
  isError: boolean;
  summary: string;
} {
  const failure = (message: string) => ({
    blocks: [{ type: "text" as const, text: message }],
    isError: true,
    summary: message,
  });
  if (!result) return failure("The tool failed to execute.");
  const blocks: BetaToolResultContentBlockParam[] = [];
  let summary = "";
  for (const item of result.content ?? []) {
    if (item.type === "text") {
      const text = item.text ?? "";
      if (!summary) summary = text.slice(0, 200);
      blocks.push({ type: "text", text });
    } else if (item.type === "image") {
      if (!summary) summary = "(image)";
      blocks.push({
        type: "image",
        source: {
          type: "base64",
          media_type: (item.mimeType ?? "image/png") as "image/png",
          data: item.data ?? "",
        },
      });
    }
  }
  if (blocks.length === 0) return failure("The tool returned no content.");
  return { blocks, isError: result.isError === true, summary };
}

/** Appends user text, merging into a trailing user message (e.g. cancelled tool results). */
function pushUserText(text: string) {
  const last = history.at(-1);
  if (last?.role === "user") {
    const content = typeof last.content === "string" ? [{ type: "text" as const, text: last.content }] : last.content;
    last.content = [...content, { type: "text", text }];
  } else {
    history.push({ role: "user", content: [{ type: "text", text }] });
  }
}

// History is append-only: nothing already sent is ever rewritten. Opus 5.5
// replays its earlier thinking blocks only while everything before them is
// byte-identical (and rejects the request outright on newer accounts), and
// an unchanged prefix is also what keeps the prompt cache warm. Old canvas
// renders therefore stay in history. The one sanctioned rewrite is the
// API's own on-demand compaction, which swaps the history for its signed
// summary block at the end of a turn (compactIfDue).

/** Whether the conversation has outgrown the auto-compact limit. */
function compactionDue(): boolean {
  const limit = settings.auto_compact_tokens;
  return limit !== null && contextUsed >= limit;
}

/** Tool result clearing, when on; see CLEAR_TRIGGER_TOKENS. */
function contextManagement() {
  if (!settings.clear_tool_results) return undefined;
  return {
    edits: [
      {
        type: "clear_tool_uses_20250919" as const,
        trigger: { type: "input_tokens" as const, value: CLEAR_TRIGGER_TOKENS },
        keep: { type: "tool_uses" as const, value: CLEAR_KEEP_TOOL_USES },
        clear_at_least: { type: "input_tokens" as const, value: CLEAR_AT_LEAST_TOKENS },
      },
    ],
  };
}

async function runTurn(text: string) {
  if (!client || !config || !prices) {
    emit({ type: "error", message: "The assistant helper was not configured." });
    return;
  }
  if (turn) {
    emit({ type: "error", message: "The assistant is busy." });
    return;
  }
  const controller = new AbortController();
  turn = controller;
  const turnPrices = prices;
  emit({ type: "turn_started" });
  pushUserText(text);

  const runner = client.beta.messages.toolRunner(
    {
      model: config.model,
      max_tokens: MAX_TOKENS,
      max_iterations: MAX_ITERATIONS,
      system: `${config.system}\n\n${config.search_guide}`,
      tools: [TOOL_SEARCH, ...tools],
      messages: history,
      // Automatic caching: the breakpoint moves to the newest block each
      // round, so the tool catalog, system prompt and history are reused.
      cache_control: { type: "ephemeral" },
      // Thinking is always on for Opus 5.5; effort is the dial (its API
      // default is also medium, set here so it doesn't drift).
      output_config: { effort: "medium" },
      // The model's notes between tool calls arrive as thinking blocks;
      // "updates" returns them as short readable summaries.
      thinking: { type: "adaptive", display: "updates" },
      // A classifier refusal is retried on the model Anthropic picks for it.
      fallbacks: "default",
      context_management: contextManagement(),
      betas: settings.clear_tool_results
        ? [...BASE_BETAS, "context-management-2025-06-27"]
        : BASE_BETAS,
      stream: true,
    },
    { signal: controller.signal },
  );

  let last: BetaMessage | undefined;
  let compacting = false;
  // The response in flight, as its stream has reported it so far: priced as
  // partial if the turn throws before `finalMessage` resolves (an object, so
  // tsc does not narrow the property to `never` in the catch).
  const inFlight: { message?: BetaMessage } = {};
  try {
    for await (const stream of runner) {
      stream.on("streamEvent", (_event, snapshot) => {
        inFlight.message = snapshot;
      });
      stream.on("text", (delta) => emit({ type: "text_delta", text: delta }));
      stream.on("thinking", (delta) => emit({ type: "progress_delta", text: delta }));
      const message = await stream.finalMessage();
      inFlight.message = undefined;

      if (compacting) {
        // The summary request the runner sent after the final reply.
        compacting = false;
        emitCost(message, turnPrices);
        reportCompaction(message);
        continue;
      }

      last = message;
      emit({ type: "message_done", stop_reason: message.stop_reason, usage: message.usage });
      emitCost(message, turnPrices);
      // Everything this request sent (cached or not) plus the reply, which
      // becomes part of the next request.
      const usage = message.usage;
      contextUsed =
        usage.input_tokens +
        (usage.cache_read_input_tokens ?? 0) +
        (usage.cache_creation_input_tokens ?? 0) +
        usage.output_tokens;
      emitContextUsage();
      reportClearedToolResults(message);

      // Compaction only ever runs when a turn ends: after the final reply,
      // never between tool calls. The runner sends the summary request next
      // and swaps its history for the returned block.
      const final = message.stop_reason !== "tool_use" && message.stop_reason !== "pause_turn";
      if (final && compactionDue() && !controller.signal.aborted) {
        compacting = true;
        emit({ type: "compaction_started", used: contextUsed });
        runner.compactBeforeNextTurn({ type: "summarize", instructions: config.compaction_instructions });
      }
    }
    if (compacting) {
      // The runner ended without handing back a summary.
      emit({ type: "compaction_failed", reason: "no summary came back" });
    }
    if (last?.stop_reason === "max_tokens") {
      emit({ type: "error", message: "The reply was cut off at the output limit." });
    } else if (last?.stop_reason === "refusal") {
      emit({ type: "error", message: "The model declined this request." });
    }
  } catch (error) {
    if (inFlight.message) {
      emitCost(inFlight.message, turnPrices, true);
      inFlight.message = undefined;
    }
    if (!controller.signal.aborted) {
      emit({ type: "error", message: errorMessage(error) });
    }
  } finally {
    // The runner keeps its own copy of the conversation, including
    // tool results that landed before a cancel or an error.
    history = [...runner.params.messages];
    turn = undefined;
    emit({ type: "turn_finished" });
  }
}

/** A compaction response: the summary block replaced the history, or nothing did. */
function reportCompaction(message: BetaMessage) {
  if (message.stop_reason !== "compaction") {
    // The history is unchanged; the next turn end tries again.
    emit({ type: "compaction_failed", reason: `the summary stopped with ${message.stop_reason}` });
    return;
  }
  const before = contextUsed;
  const summary = message.usage.iterations?.find((entry) => entry.type === "compaction");
  // The summary is what remains of the conversation; the next response's
  // usage replaces this estimate with the real figure.
  contextUsed = summary?.output_tokens ?? 0;
  emit({ type: "compacted", before, after: contextUsed });
  emitContextUsage();
}

/** Tells the panel when the API cleared old tool results from this request. */
function reportClearedToolResults(message: BetaMessage) {
  for (const edit of message.context_management?.applied_edits ?? []) {
    if (edit.type === "clear_tool_uses_20250919") {
      emit({
        type: "tool_results_cleared",
        tool_uses: edit.cleared_tool_uses,
        tokens: edit.cleared_input_tokens,
      });
    }
  }
}

function errorMessage(error: unknown): string {
  if (error instanceof Anthropic.APIError) {
    const detail = (error.error as { error?: { message?: string } } | undefined)?.error?.message;
    return `API error ${error.status ?? ""}: ${detail ?? error.message}`.trim();
  }
  return error instanceof Error ? error.message : String(error);
}

function handle(message: HostMessage) {
  switch (message.type) {
    case "configure":
      configure(message);
      emit({ type: "ready" });
      break;
    case "send":
      void runTurn(message.text);
      break;
    case "cancel":
      turn?.abort();
      break;
    case "tool_result": {
      const resolve = pendingCalls.get(message.call_id);
      pendingCalls.delete(message.call_id);
      resolve?.(message.result);
      break;
    }
    case "settings":
      // Applies from the next turn; a running turn keeps what it started with.
      settings = message.settings;
      break;
    case "reset":
      turn?.abort();
      history = [];
      contextUsed = 0;
      emitContextUsage();
      break;
  }
}

const input = createInterface({ input: process.stdin });
input.on("line", (line) => {
  if (!line.trim()) return;
  try {
    handle(JSON.parse(line) as HostMessage);
  } catch (error) {
    emit({ type: "error", message: `Bad message from the app: ${errorMessage(error)}` });
  }
});
// The app closing our stdin means it is gone or closed the session.
input.on("close", () => process.exit(0));
// The stdio protocol between the app (its helper session) and
// this helper: one JSON object per line in each direction.

import type { Price } from "./pricing";

/** One entry of the app's MCP-format tool catalog. */
export type CatalogTool = {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
};

/** An MCP CallToolResult, as AgentServer.execute returns it. */
export type CallToolResult = {
  // text carries `text`; image carries base64 `data` and `mimeType`.
  content?: Array<{ type: string; text?: string; data?: string; mimeType?: string }>;
  isError?: boolean;
};

/** The Assistant panel's Chat Settings that shape requests. */
export type ChatSettings = {
  /** Compact at the end of a turn once context reaches this many tokens; null never compacts. */
  auto_compact_tokens: number | null;
  /** Let the API clear old tool results past a threshold (off by default). */
  clear_tool_results: boolean;
};

/** The table a price came from: the bundled snapshot (as of its LiteLLM
 *  commit's date), the cached copy or a fresh fetch (as of `fetched_at`), and
 *  why it was not refreshed, if it was not. */
export type PriceSource = { kind: "bundled" | "cached" | "fetched"; as_of: string /* bundled: litellm_commit_date; else fetched_at */; problem?: string };

// App -> helper

export type Configure = {
  type: "configure";
  api_key: string;
  model: string;
  system: string;
  tools: CatalogTool[];
  /** Tools the model sees up front; every other catalog entry is deferred and found through tool search. */
  core_tools: string[];
  /** Appended to the system prompt after a blank line: what tool search can find. */
  search_guide: string;
  /** What the end-of-turn compaction summary must carry. */
  compaction_instructions: string;
  /** The app's base-URL override (an environment variable of its own), for pointing at a test server. */
  api_base?: string;
  settings: ChatSettings;
  /** The absolute path of the price cache; absent = the bundled table only, and no refresh. */
  price_cache?: string;
  /** Where the refresh fetches LiteLLM's table; absent = LITELLM_URL. */
  price_feed?: string;
};

export type HostMessage =
  | Configure
  | { type: "send"; text: string }
  | { type: "cancel" }
  | { type: "reset" }
  /** Chat Settings changed; applies from the next turn. */
  | { type: "settings"; settings: ChatSettings }
  /** The answer to a tool_request; result null means the app could not run it. */
  | { type: "tool_result"; call_id: string; result: CallToolResult | null };

// Helper -> app.

export type HelperEvent =
  | { type: "ready" }
  | { type: "turn_started" }
  | { type: "text_delta"; text: string }
  /** A progress note between tool calls (a thinking block under display "updates"). */
  | { type: "progress_delta"; text: string }
  | { type: "message_done"; stop_reason: string | null; usage: unknown }
  /** Tokens in the conversation after the last response; limit is the model's window (null if unknown). */
  | { type: "context_usage"; used: number; limit: number | null }
  | { type: "tool_call"; name: string; arguments: unknown }
  /** Run a tool and answer with tool_result. The arguments stay a JSON string, as the dispatcher takes them. */
  | { type: "tool_request"; call_id: string; name: string; arguments_json: string }
  | { type: "tool_result"; name: string; is_error: boolean; summary: string }
  | { type: "error"; message: string }
  /** The turn's final reply pushed context past the auto-compact limit; a summary is being written. */
  | { type: "compaction_started"; used: number }
  /** The history is now the summary block; before/after are tokens in context. */
  | { type: "compacted"; before: number; after: number }
  /** No summary came back; the history is unchanged and the next turn end tries again. */
  | { type: "compaction_failed"; reason: string }
  /** The API cleared old tool results from what the model saw on one request. */
  | { type: "tool_results_cleared"; tool_uses: number; tokens: number }
  /** Once per configure: before `ready` if no refresh is due, else when it settles. */
  | { type: "prices"; source: PriceSource }
  /**
   * Per response, at the turn's prices: after message_done; for a summary, before compacted/compaction_failed.
   * `partial`: a response cut short (a cancel or an error), priced from the usage its stream had reported, before any error.
   */
  | { type: "cost"; model: string; usage: unknown; cost: Price; prices: PriceSource; partial?: true }
  | { type: "turn_finished" };

import AppKit

/// The Assistant tab's transcript: a scroll view owning ONE non-editable,
/// selectable text view (TextKit 1), the entries in order with one "\n"
/// between them, so a selection and a plain-text copy cross entries (spec
/// §11 AI-17). Each entry is a range of that text, kept in `spans`; a reply
/// that is still extending edits only its own range. Scrolled to the newest
/// line whenever an entry is appended or extended. It draws the transcript
/// it is handed and keeps none of it (spec §11 AI-4: the entries are
/// `EditorViewController.assistantTranscript`'s). Road map 12 A2.
///
/// One text view has no subview per entry, so the layout dump reads the
/// entries as parts this view names (`UISnapshotParts`, dev only): the
/// `assistant.entry.<kind>` records the proofs read.
final class AssistantTranscriptView: NSScrollView {
    private static let inset: CGFloat = 10
    let textView: NSTextView
    /// Each entry's kind and its UTF-16 range in the text, in order.
    private var spans: [(kind: AssistantEntry.Kind, range: NSRange)] = []

    init() {
        textView = TranscriptTextView(usingTextLayoutManager: false)
        super.init(frame: .zero)
        hasVerticalScroller = true
        autohidesScrollers = true
        drawsBackground = false
        borderType = .noBorder
        textView.isEditable = false
        textView.isSelectable = true
        textView.drawsBackground = false
        textView.isRichText = true
        textView.textContainerInset = NSSize(width: Self.inset, height: 8)
        textView.textContainer?.lineFragmentPadding = 0
        textView.textContainer?.widthTracksTextView = true
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.minSize = .zero
        textView.maxSize = NSSize(
            width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
        textView.autoresizingMask = [.width]
        textView.frame = NSRect(origin: .zero, size: contentSize)
        documentView = textView
        // Adopting it runs the text view's `sizeToFit`, which leaves its
        // origin at minus its new height (measured, #182); put it back at 0.
        textView.setFrameOrigin(.zero)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AssistantTranscriptView does not support NSCoder")
    }

    /// The text view is never shorter than the clip view, so a click below a
    /// short transcript lands in the text (#182).
    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        textView.minSize = NSSize(width: 0, height: contentSize.height)
        textView.sizeToFit()
    }

    // MARK: - Drawing the transcript

    func reload(_ entries: [AssistantEntry]) {
        storage?.setAttributedString(NSAttributedString())
        spans = []
        for entry in entries { add(entry) }
        scrollToNewest()
    }

    func apply(_ change: AssistantTranscriptChange) {
        switch change {
        case .appended(let entry):
            add(entry)
            scrollToNewest()
        case .extended(let index, let text):
            guard spans.indices.contains(index) else { return }
            extend(index, to: text)
            scrollToNewest()
        case .cleared:
            reload([])
        case .usage, .conversationCost:
            break
        }
    }

    /// Each entry's kind, text and rect, in order, in THIS view's coordinates.
    func entryLayout() -> [(kind: AssistantEntry.Kind, text: String, rect: NSRect)] {
        guard let storage, let layout = textView.layoutManager,
            let container = textView.textContainer
        else { return [] }
        layout.ensureLayout(for: container)
        let origin = textView.textContainerOrigin
        let text = storage.string as NSString
        return spans.map { span in
            let glyphs = layout.glyphRange(forCharacterRange: span.range, actualCharacterRange: nil)
            var rect = layout.boundingRect(forGlyphRange: glyphs, in: container)
            rect.origin.x += origin.x
            rect.origin.y += origin.y
            return (span.kind, text.substring(with: span.range), convert(rect, from: textView))
        }
    }

    private var storage: NSTextStorage? { textView.textStorage }

    private func add(_ entry: AssistantEntry) {
        guard let storage else { return }
        storage.beginEditing()
        if !spans.isEmpty {
            // The separator ends the previous entry's last paragraph, so it
            // takes that paragraph's attributes.
            let attributes = storage.length > 0
                ? storage.attributes(at: storage.length - 1, effectiveRange: nil)
                : Self.attributes(entry.kind, first: false, index: spans.count)
            storage.append(NSAttributedString(string: "\n", attributes: attributes))
        }
        let start = storage.length
        let styled = Self.styled(entry.text, entry.kind, index: spans.count)
        storage.append(styled)
        storage.endEditing()
        spans.append((entry.kind, NSRange(location: start, length: styled.length)))
    }

    /// Entry `index`'s text is now `text`: only the new suffix is inserted
    /// when the old text is a non-empty prefix of it; otherwise the entry's
    /// range is replaced. The spans after it shift.
    private func extend(_ index: Int, to text: String) {
        guard let storage else { return }
        let span = spans[index]
        let old = (storage.string as NSString).substring(with: span.range)
        let styled = Self.styled(text, span.kind, index: index)
        let replaced: NSRange
        let inserted: NSAttributedString
        if !old.isEmpty, text.hasPrefix(old) {
            let oldLength = (old as NSString).length
            replaced = NSRange(location: NSMaxRange(span.range), length: 0)
            inserted = styled.attributedSubstring(
                from: NSRange(location: oldLength, length: styled.length - oldLength))
        } else {
            replaced = span.range
            inserted = styled
        }
        guard replaced.length > 0 || inserted.length > 0 else { return }
        storage.beginEditing()
        storage.replaceCharacters(in: replaced, with: inserted)
        storage.endEditing()
        let delta = inserted.length - replaced.length
        spans[index].range.length += delta
        for later in spans.indices where later > index {
            spans[later].range.location += delta
        }
    }

    /// `text` in `kind`'s font and colour; its first paragraph carries the
    /// gap above the entry, the rest none.
    private static func styled(
        _ text: String, _ kind: AssistantEntry.Kind, index: Int
    ) -> NSAttributedString {
        let result = NSMutableAttributedString(
            string: text, attributes: attributes(kind, first: false, index: index))
        let whole = text as NSString
        let firstEnd = whole.paragraphRange(for: NSRange(location: 0, length: 0))
        if firstEnd.length > 0 {
            result.setAttributes(attributes(kind, first: true, index: index), range: firstEnd)
        }
        return result
    }

    /// The person's line opens a new exchange: a wider gap above it.
    private static func attributes(
        _ kind: AssistantEntry.Kind, first: Bool, index: Int
    ) -> [NSAttributedString.Key: Any] {
        let paragraph = NSMutableParagraphStyle()
        paragraph.paragraphSpacingBefore = !first || index == 0 ? 0 : (kind == .person ? 14 : 6)
        let font: NSFont
        let colour: NSColor
        switch kind {
        case .person:
            font = DS.sans(12, weight: .semibold)
            colour = DS.textStrong
        case .reply:
            font = DS.sans(12)
            colour = DS.textStrong
        case .progress:
            font = DS.sans(11)
            colour = DS.textFaint
        case .meta:
            font = DS.mono(10)
            colour = DS.textMuted
        case .error:
            font = DS.sans(11)
            colour = DS.meterClip
        }
        return [.font: font, .foregroundColor: colour, .paragraphStyle: paragraph]
    }

    /// The newest line into view. The text view is flipped, so the end is
    /// its full height less what the clip view shows.
    private func scrollToNewest() {
        layoutSubtreeIfNeeded()
        if let layout = textView.layoutManager, let container = textView.textContainer {
            layout.ensureLayout(for: container)
        }
        textView.sizeToFit()
        let clip = contentView
        let y = max(0, textView.frame.height - clip.bounds.height)
        clip.scroll(to: NSPoint(x: 0, y: y))
        reflectScrolledClipView(clip)
    }
}

/// The transcript's text view: it copies plain text only. The type is the
/// legacy string name NSTextView writes by (`writeSelection` answers false
/// for `.string`, measured on macOS 26), which the pasteboard also offers as
/// `public.utf8-plain-text`.
private final class TranscriptTextView: NSTextView {
    override var writablePasteboardTypes: [NSPasteboard.PasteboardType] {
        [NSPasteboard.PasteboardType("NSStringPboardType")]
    }
}

#if FRAMEJOB_DEV_TOOLS
extension AssistantTranscriptView: UISnapshotParts {
    /// One `assistant.entry.<kind>` part per entry, for the layout dump.
    func snapshotParts() -> [UISnapshotPart] {
        entryLayout().map { entry in
            UISnapshotPart(
                id: "assistant.entry.\(entry.kind.rawValue)", text: entry.text, rect: entry.rect)
        }
    }
}
